"""
quality_filter.py
Quality filters for code samples.
"""

import re
from config import (
    REMOVE_AUTOGENERATED,
    REMOVE_MINIFIED
)

AUTOGENERATED = (
    "generated by",
    "auto-generated",
    "do not edit",
    "automatically generated",
    "@generated"
)

def has_autogenerated_notice(code):
    if not REMOVE_AUTOGENERATED:
        return False
    lower = code.lower()
    return any(
        phrase in lower
        for phrase in AUTOGENERATED
    )

def looks_minified(code):
    if not REMOVE_MINIFIED:
        return False
    lines = code.splitlines()
    if len(lines) <= 2 and len(code) > 2000:
        return True
    average = (
        sum(len(i) for i in lines)
        /
        max(len(lines), 1)
    )
    return average > 400

def has_excessive_repetition(code):
    lines = [
        i.strip()
        for i in code.splitlines()
        if i.strip()
    ]

    if len(lines) < 10:
        return False
    unique = len(set(lines))
    ratio = unique / len(lines)
    return ratio < 0.30

def has_suspicious_characters(code):
    return bool(
        re.search(
            r"[\x00-\x08\x0B\x0C\x0E-\x1F]",
            code
        )
    )


def passes_quality(sample):
    code = sample["output"]
    if has_autogenerated_notice(code):
        return False
    if looks_minified(code):
        return False
    if has_excessive_repetition(code):
        return False
    if has_suspicious_characters(code):
        return False
    return True